import unittest

from counts import word_counts


class WordCountsTests(unittest.TestCase):
    def test_normal_sentence(self):
        self.assertEqual(word_counts("One fish two fish red fish blue fish"),
                         {"one": 1, "fish": 4, "two": 1, "red": 1, "blue": 1})

    def test_case_insensitive(self):
        self.assertEqual(word_counts("APPLE apple Apple aPpLe"), {"apple": 4})

    def test_apostrophes_and_numbers_separate_tokens(self):
        self.assertEqual(word_counts("can't CAN'T abc123def 42abc"),
                         {"can": 2, "t": 2, "abc": 2, "def": 1})

    def test_punctuation_underscores_and_whitespace(self):
        self.assertEqual(word_counts("\tHello_world!\nhello-world. world\r"),
                         {"hello": 2, "world": 3})

    def test_unicode_is_not_ascii(self):
        self.assertEqual(word_counts("café CAFÉ naïve"),
                         {"caf": 2, "na": 1, "ve": 1})
        self.assertEqual(word_counts("İ ı ſ K ß 中文 😀"), {})
        self.assertEqual(word_counts("aİb aKb aſb"), {"a": 3, "b": 3})

    def test_empty_and_no_words(self):
        for text in ("", " \n\t", "12345!@#$%^&*()_", "中文"):
            with self.subTest(text=text):
                self.assertEqual(word_counts(text), {})

    def test_all_ascii_letters(self):
        alphabet = "abcdefghijklmnopqrstuvwxyz"
        self.assertEqual(word_counts(alphabet + " " + alphabet.upper()), {alphabet: 2})

    def test_new_dict_each_call(self):
        first = word_counts("hello")
        first["hello"] = 99
        self.assertEqual(word_counts("hello"), {"hello": 1})


if __name__ == "__main__":
    unittest.main()
